//! The `Permissions, trust and offline mode` rows of the settings page, in page order (issue #2042, R3): the docs view of
//! the descriptor table, rendered into `oxa/docs/pages/settings.md` by
//! `tools/ci/settings_table.py`. Edit a row here and rerun the tool.

use super::{row, PageRow};

/// The section heading shown on the page.
pub(super) const TITLE: &str = "Permissions, trust and offline mode";

#[rustfmt::skip]
pub(super) const ROWS: &[PageRow] = &[
    row("oxa.allowHomeCwd", "bool", "`false`", "allow oxa to start in the home directory, `/` or a parent of home. Without it print, JSON and RPC modes refuse and interactive mode asks. An explicit `--yolo` or `--auto` on the command line also allows it, with a warning and no question; the environment variable `OXA_ALLOW_HOME_CWD` also allows it. User settings only. See [security.md](security.md#starting-in-your-home-directory)"),
    row("oxa.approval.always", "list", "`[]`", "exact `<rule> <command>` keys written by \"Always allow\" in the dangerous-command prompt (#1512). Each key matches one literal command of one rule. Shell parameter or command substitution markers anywhere in the command make saved grants inapplicable. Remove a line to revoke it. User settings only"),
    row("oxa.approval.dangerous", "list", "`[]`", "rules for dangerous commands, matched on the parsed command (#1512). `[]` (the default) is all built-in rules. `+id` adds a rule, `-id` removes one, `+cmd:<words>` adds a rule for a command (`+cmd:terraform destroy`), and a list without `+`/`-` entries replaces the built-in set (a plain `cmd:<words>` there turns the built-in rules off). Built-in ids: `rm-recursive-outside`, `git-push-force`, `credential-write`, `pipe-to-shell`, `disk-destroy`, `chmod-recursive-open`, `sudo`, `sql-drop`, `kill-foreign`, `oxa-self-approve`, `eval-dynamic`, `credential-read`, `git-hook-write`, `unparsed`. `credential-read` and `git-hook-write` are approval prompts, not a sandbox; `+cmd:<words>` also extends the token-printing commands `credential-read` knows. Unknown entries are ignored with a warning. Separately from these rules, a built-in publish check always runs: pushing the session's own non-default branch to `origin` with an explicit source refspec and `gh pr create|edit|comment` or read-only `gh` need no question, but a push with no refspec, a push to the default branch, a force push, a merge, a push elsewhere, an unresolved Git subcommand (a name that is not a builtin recognized by the classifier, so it can be a configured alias or an external `git-*` executable), or any command chained with a publish command asks (yolo never asks). A later sequential repository mutation is safe (`git push && git switch main`), while a mutation in the same concurrent pipeline asks (`git push | git switch main`). User settings only"),
    row("oxa.approval.rootActions", "list", "`[]`", "root actions you name, so oxa does not ask before them (#784): each entry is `<name>: <absolute executable> [arguments]` where `*` matches exactly one argument, for example `boot: /usr/bin/bootctl set-default *`. Only a literal `/usr/bin/sudo` (optionally `-n`) command with the default shell and no command prefix can match. The target must be a canonical absolute executable path, owned by root and not writable by group or others, including its parent directories. Its device and inode must still match the ones recorded when the session loaded the action. Shell expansion, pipes and redirects keep the question; every other rule still applies. Only your interactive session uses the list: workers, subagents, headless and `oxa work` runs never do. Sudo still decides whether a password is needed. See [security.md](security.md#grants-named-root-actions-and-the-sudo-password). Invalid entries, including old bare target names, are ignored with a warning. User settings only"),
    row("oxa.approval.unattended", "enum", "`\"auto\"`", "what an unattended run (no one to ask: workers, subagents, headless goals) does with a dangerous command (#1512). `auto` refuses it under the OS sandbox and requests approval without it; `refuse` always refuses; `request` files a request for the owner (`oxa send <session> --approve <id> once|session|always|deny`, or the Lead web approvals page). A `session` answer lasts for the current run and expires when a persisted session is resumed. Shell input classified as `pipe-to-shell` requires direct owner review because the command text cannot identify the input bytes for a retry. Nothing waits for an answer. User settings only"),
    row("oxa.mode", "`plan` / `workspace` / `ask`", "`workspace`", "table mode at start"),
    row("defaultProjectTrust", "`ask` / `always` / `never`", "`always`", "what happens in a project that is not trusted yet: `always` (default) trusts it, `ask` asks once per project in the interface and skips its resources in print, JSON and RPC runs, `never` skips them everywhere; user settings only. See [security.md](security.md#project-trust)"),
    row("projectTrustPolicy", "`folder` / `content`", "`folder`", "trusted folders load new or changed resources with a notice; `content` requires fresh approval of changed executable project files. User settings only. See [security.md](security.md#project-trust)"),
    row("oxa.offline", "bool", "`false`", "same as `--offline`; user settings only"),
    row("oxa.engine.allowRemote", "bool", "`false`", "allow an engine on another host; user settings only"),
    row("oxa.engine.inProcessLocal", "bool", "`false`", "select the in-process owned local engine, including offline; user settings only"),
    row("oxa.inbox.headless", "bool", "`true`", "a headless print or JSON run (`--mode json`) of a persisted session whose goal is pursuing, or an `oxa work` worker, takes `oxa send` follow-ups from that session's inbox for the length of the run. Each message is an ordinary follow-up user message, at most 256 KiB and 64 queued; a larger file stays on disk. Other runs without a pursuing goal never watch the inbox, and `false` turns this off, `oxa work` workers included. Read from the user settings file only; a project file cannot change it"),
    row("oxa.local", "object", "`{}`", "literal native binary/model/arguments/environment and model limits; user settings only; `oxa local add` writes it from the engine's admission report, including the cache options (state cache, session RAM, prefix cache, 8 checkpoints; owner values win) ([Local models](cli.md#local-models)); see [native local configuration](../../oxc-local/CONFIGURATION.md)"),
    row("oxa.a2a.enabled", "bool", "`true`", "sessions accept follow-ups and control (steer, pause, resume, cancel) from the lead over a local authenticated channel, from the same user only. `false`: file inbox only, and `nativeSteering` is refused. User settings only. See [security.md](security.md#agent-control-channel)"),
    row("oxa.lead.shadow", "bool", "`true`", "the read-only `oxa lead --shadow` proposal preset; `false` turns it off; user settings only; no live runner actions"),
    row("oxa.engine.inProcessCloud", "bool", "unset", "select the in-process Rust cloud gateway for sessions and model discovery. Unset is on when the owner's key file has an `openrouter`, `openai` or `anthropic` key or `oxa login chatgpt` was done; `false` opts out. User settings only"),
    row("oxa.cloud.opencode.enabled", "bool", "on when a key exists", "OpenCode Go is on when the `opencode` key exists in the protected cloud key file and the run has an actual `--model` argument naming a Go model (including a delegated worker or nested child), or an owner model scope that is not a local alias; `false` opts out everywhere; project settings and restored sessions cannot enable it; offline mode refuses; user settings only"),
    row("oxa.cloud", "object", "`{}`", "native cloud models, prices, USD budget and subscription caps; user settings only; see below"),
    row("oxa.lead.serve", "object", "`{}`", "the lead web access scaffold: `enabled`, `identity` (`local` or `tailscale`), `bind` (a loopback address), `port`, `allowed_identities`. Off by default and no listener is installed yet; the default identity mode is `local` unless selected otherwise; user settings only. See [lead-web.md](lead-web.md)"),
    row("oxa.lead.sessionId", "string", "unset", "exact ID of the dedicated Lead Session created by the native owner operation, from owner-private user settings. Free text is disabled when unset."),
    row("oxa.lead.attachSessionId", "string", "unset", "exact ID of a running owner session the lead web page attaches to (live transcript, messages through its inbox like `oxa send`), from owner-private user settings; with `oxa.lead.serve.owner_chat` it replaces the dedicated Lead chat; restart the service after changing it."),
    row("oxa.lead.model", "string", "unset", "exact model id the Lead conversation resolves through the normal `--model` selector and gateway; user settings only, read from the owner-private settings file. Unset keeps the ordinary startup model; a route that does not resolve is reported, never silently replaced. A metered model still needs its daily USD cap, so choose a subscription route while the cap is absent."),
    row("oxa.envNote", "bool", "unset", "append the environment note to each prompt you send: the first one in a session (and the first of a new day, or after a compaction) gets a short `<env>` block with the date, time, time zone, locale, kernel, model, context size, thinking level and permission mode; later ones get `[local time HH:MM ZONE]`. It is never put in the system prompt, so the prompt cache stays exact. Unset is on; `OXA_ENV_NOTE=0` or `=1` overrides it for one run"),
    row("oxa.github.tokenCommand", "list", "`[]`", "trusted argv that prints a GitHub token for `oxa work --publish` and lane CI; configured tokens are masked in shell output, never injected into shell environments; operands must be trusted absolute executable paths; empty uses the stored GitHub login; user settings only"),
    row("oxa.github.tokenTtlSeconds", "number", "`300`", "seconds between token lookups for networked bash (configured tokens are only for masking); `0` reads on each use; a rejected stored login invalidates the cache; user settings only"),
    row("oxa.sandbox.net", "`on` / `off`", "`on`", "network for bash in workspace and ask modes; `off` holds without the OS sandbox too (bash then runs through bubblewrap without network, or is refused)"),
    row("oxa.sandbox.allowHomeWrite", "bool", "`false`", "make the home directory the bash workspace when oxa starts in it, in every mode (its folders and files writable; dotfiles, dot-folders, `~/bin` and the home folder itself stay read-only; never `/` or a parent of home). In interactive mode confirming the start question does the same. User settings only. See [security.md](security.md#starting-in-your-home-directory)"),
    row("oxa.sandbox.interactive", "bool", "`false`", "the OS sandbox (bubblewrap) for bash in an attended run (the TUI, a person's `oxa -p`, the lead chat). Off by default: bash runs with your rights and dangerous commands ask. Exec hooks keep their dedicated sandbox. `--sandbox` turns it on for one run. Yolo has no OS sandbox. User settings only"),
    row("oxa.sandbox.readPaths", "list", "`[]`", "extra read-only paths for bash; `~/` is expanded; user settings only"),
    row("oxa.sandbox.unattended", "bool", "`true`", "the OS sandbox (bubblewrap) for bash in an unattended run, including a subagent, a lead worker, `oxa work`, an ownerless RPC host, or a headless run that starts or resumes a pursuing goal. Stays on by default; set `false` only if you accept bash without it there. User settings only"),
    row("oxa.sandbox.writePaths", "list", "`[]`", "extra writable paths for bash; `~/` is expanded; user settings only"),
    row("oxa.sandbox.sockets", "list", "`[]`", "host runtime sockets (for example `/run/docker.sock`, `/run/podman/podman.sock`) that stay reachable in network-enabled sandboxed bash with Bubblewrap FD binds; absolute paths of existing sockets; user settings only, a project file cannot list them. The start notice names each one. The start notice warns about the Docker socket’s root access. An online command fails closed if a configured socket cannot be pinned or Bubblewrap cannot mount the descriptor. Offline, a listed socket is masked at its path instead, and a socket below a writable mount (the workspace, a write bind, `$HOME` or `/tmp`) is refused: its mask could be moved away by renaming the parent, so relocate the socket or drop the setting. Yolo bash has no sandbox and needs no entry"),
    row("oxa.sandbox.gitConfigAllow", "list", "`[\"branch.*\", \"user.*\", \"remote.*.fetch\"]`", "git config keys that sandboxed bash may change in the repository's `config` (`git branch -m`, `git config user.name`, a changed fetch refspec work); `*` matches one dotted component or a subsection, keys compare case-insensitively. Any other change is restored right after the command, with a note in its output, because git runs some keys (`core.hooksPath`, `alias.*`, `core.fsmonitor`) outside the sandbox later; an empty list restores every change; user settings only"),
    row("oxa.sandbox.scratchWarnSize", "string", "`20GiB`", "warn (never block) when this session's sandbox `/tmp` scratch holds more than this: one line is added to the command output, again only after the size has doubled; a size such as `20GiB` or `512MiB`, `off` disables; user settings only"),
];
